/**
 * compare.run: Compares a rebuild (a project, or a second map file) with its original (default: the project's
 * map_stats.reference, else the shipped map it overlays): the score with its parts, whether it is within the
 * band (indoor 97 %, outdoor 90 %), the worst places (indoor the 40 worst stand points, outdoor the 12 worst
 * blocks of 16 x 16 cells), every stand point's or block's score as a heat map, the floor one map has and the
 * other has not, and the full report of `oymap compare --json` as `report`. Seconds to tens of seconds: lane J.
 */
export type CompareRunParams = {
  map: MapTarget;
  /** The world of a shipped map (mm6, mm7, mm8, mm9); a project names its own. */
  world?: string;
  /** Read with the session's mount of installed builds in front of the asset root (after build.install). */
  built?: boolean;
  /**
   * The original's map file (default: the project's map_stats.reference, else its base). A shipped map's file
   * name, never a path.
   */
  original?: string;
  /** The original's world (default: the project's world, else `world`). */
  original_world?: string;
};
export type CompareRunResult = {
  kind: "indoor" | "outdoor";
  original: string;
  rebuilt: string;
  world: string;
  score: number;
  band: {
    /** The band's lower edge: 0.97 indoor, 0.9 outdoor (HANDOFF.md, "Within bands"). */
    at_least: number;
    within: boolean;
  };
  parts: {
    /**
     * indoor: shape, textures, offsets; outdoor: heights, relief, cliffs, rim, water, ground, roads, buildings,
     * decorations, spawns, events.
     */
    id: string;
    title: string;
    /** Share of the score (the weights add up to 1; offsets are reported with 0). */
    weight: number;
    score: number;
    /** What the part counted, in one sentence. */
    what: string;
  }[];
  /**
   * How much higher the whole rebuild lies than the original (indoor; 0 outdoors): the Compare view moves the
   * original by it.
   */
  vertical_offset: number;
  worst: {
    /** The original's sector (indoor) or the block of 16 x 16 cells (outdoor, A1 the north-west). */
    name: string;
    /** A stand point on the original's floor (indoor), or a block's middle on the original's land (outdoor). */
    at: Point3i;
    score: number;
    /** What differs there most, in one sentence. */
    what: string;
    /** Indoor: where to look to see the most of what differs (0 east, counter-clockwise). */
    yaw_radians?: number;
  }[];
  heat: {
    /**
     * The side of the square each point stands for, in world units (indoor the stand points' step, outdoor a
     * block of 16 cells: 8192).
     */
    cell: number;
    /**
     * [x, y, score in thousandths] of every stand point (indoor; -1 where the rebuild has no floor) or block
     * middle (outdoor).
     */
    points: [number, number, number][];
  };
  floor_missing_in_rebuild: Point3i[];
  floor_only_in_rebuild: Point3i[];
  notes: Strings;
  /**
   * The full report (`oymap compare --json`): method, totals, sectors or regions, texture pairs, offsets,
   * buildings ...
   */
  report: JsonObject;
};

/**
 * edit.apply: Applies a list of operations as one transaction. Nothing is written unless every operation applies
 * and, unless allow_errors, no issue of severity error appears that was not there before. The files changed are
 * written in canonical form with the keys of format 1; a person's first change (author user) marks the project
 * as edited by hand (project.yml edited_by_hand).
 */
export type EditApplyParams = {
  project: ProjectPath;
  ops: Op[];
  /** Apply only when the project is at this revision; otherwise the error stale_revision. */
  expect_revision?: Revision;
  /** Check and report, write nothing. */
  dry_run?: boolean;
  /** Write even when the change adds issues of severity error. For tests and deliberate steps by agents. */
  allow_errors?: boolean;
  /** Who makes the change, kept in the history entry: user, or agent:<name> (default agent). */
  author?: string;
  /** A short label for the history entry. */
  label?: string;
  /**
   * A repeated edit ("drag door:gate speed"): folded into the latest history entry when that one has the same
   * author and merge key, is the latest and is less than 5 seconds old (S5_BROWSER_EDITOR.md 2.6 item 6).
   */
  merge_key?: string;
  /**
   * With expect_revision stale: apply on the current revision when nothing the operations touch changed since
   * (or their test steps hold), instead of refusing (2.7). The browser always sets it.
   */
  rebase?: boolean;
};
export type EditApplyResult = {
  /** Whether files were written: false for a dry run and for a change that changes nothing. */
  applied: boolean;
  revision_before: Revision;
  /** The revision after the transaction (for a dry run: the one it would give). */
  revision_after: Revision;
  /** The semantic diff: "objects.yml: added door:gate", "rooms.yml: room:hall changed outline". */
  changes: Strings;
  /** An edit made outside the tool, found and recorded before this transaction. */
  outside_changes: Strings;
  new_issues: Issues;
  fixed_issues: Issues;
  /**
   * Each file the transaction changes, as it is (or for a dry run would be) after it, in canonical form: the
   * client replaces its copy with these.
   */
  files: FileTrees;
  /** Ids the core gave to added objects without one, as file#id ("objects.yml#light:hall_1"). */
  ids_allocated?: Strings;
  /** Keys the core wrote for sub-objects without one ("rooms.yml rooms[3].pillars[0]: pillar1"). */
  keys_allocated?: Strings;
  /**
   * Things worth knowing that did not stop the change: a lua text naming a renamed id, lock entries and pins
   * that followed a rename.
   */
  notes?: Strings;
  /** The history entry written (absent for a dry run or no change). */
  sequence?: number;
  /** The change was folded into the latest entry (merge_key). */
  merged?: boolean;
  /** A rebase: the entries since expect_revision it was applied over. */
  rebased_over?: number[];
  hand_edited?: HandMark;
  /**
   * Objects a person changed last that this change changes, as far as the kept history shows (told to agents in
   * a project edited by hand).
   */
  hand_objects?: Strings;
  /**
   * The notice of the outside entry recorded before this change: a project edited by hand rewritten from outside
   * (objects a person changed last that it replaced, keys it dropped) and the step to revert it.
   */
  outside_notice?: Strings;
  /** The outside entry recorded before this change. */
  outside_sequence?: number;
};

/**
 * edit.history: The project's history, newest last: transactions and edits found on disk (outside), each with
 * its author, label, time and semantic changes. An entry later undone says so (`undone`); a revert entry (S5b1,
 * D4) names the entry it reverts (`reverts`). Records an edit made outside the tool first, as project.status
 * does.
 */
export type EditHistoryParams = {
  project: ProjectPath;
  /** At most this many of the latest entries (default 50). */
  limit?: number;
};
export type EditHistoryResult = {
  revision: Revision;
  /** Entries in the history (all, not only those returned). */
  count: number;
  entries: HistoryEntry[];
};

/**
 * edit.undo: Undo (S5_BROWSER_EDITOR.md 2.7): a new history entry that reverts the author's latest entry that is
 * neither an undo nor reverted already, object by object, validated like any transaction. An object changed
 * since is a conflict, left alone unless force. The revert of a rename runs as the opposite rename; the id
 * lock's numbers and the hand-edit mark are never undone.
 */
export type EditUndoParams = {
  project: ProjectPath;
  /**
   * Whose undo or redo, and the revert entry's author: user, or agent:<name> (default user for edit.undo and
   * edit.redo).
   */
  author?: string;
  /**
   * Put back objects changed since the reverted entry too (otherwise they are listed as conflicts and left
   * alone).
   */
  force?: boolean;
  /** Write even when the revert adds issues of severity error (a person confirming). */
  allow_errors?: boolean;
  /** The revert entry's label (default: undo: <the reverted entry's label>). */
  label?: string;
};
export type EditUndoResult = {
  revision: Revision;
  /** The entry reverted. */
  reverts: number;
  /** The revert entry written (absent when nothing changed). */
  sequence?: number;
  /**
   * "undone: rooms.yml: room:hall changed outline" (redone: for redo, reverted: for edit.revert): what the
   * revert changed.
   */
  changes: Strings;
  /** Objects (file#id) the reverted entry changed and someone changed since: left alone unless force. */
  conflicts: Strings;
  notes?: Strings;
  new_issues: Issues;
  /** Each file the revert changes, in canonical form. */
  files: FileTrees;
};

/**
 * edit.redo: Redo: reverts the author's latest undo not reverted yet, while the author has made no other change
 * since (a new change ends the redo chain).
 */
export type EditRedoParams = {
  project: ProjectPath;
  /**
   * Whose undo or redo, and the revert entry's author: user, or agent:<name> (default user for edit.undo and
   * edit.redo).
   */
  author?: string;
  /**
   * Put back objects changed since the reverted entry too (otherwise they are listed as conflicts and left
   * alone).
   */
  force?: boolean;
  /** Write even when the revert adds issues of severity error (a person confirming). */
  allow_errors?: boolean;
  /** The revert entry's label (default: undo: <the reverted entry's label>). */
  label?: string;
};
export type EditRedoResult = {
  revision: Revision;
  /** The entry reverted. */
  reverts: number;
  /** The revert entry written (absent when nothing changed). */
  sequence?: number;
  /**
   * "undone: rooms.yml: room:hall changed outline" (redone: for redo, reverted: for edit.revert): what the
   * revert changed.
   */
  changes: Strings;
  /** Objects (file#id) the reverted entry changed and someone changed since: left alone unless force. */
  conflicts: Strings;
  notes?: Strings;
  new_issues: Issues;
  /** Each file the revert changes, in canonical form. */
  files: FileTrees;
};

/**
 * edit.revert: Reverts any one entry of the history ("Revert this entry"), object by object, as an undo does:
 * for an outside rewrite of a project edited by hand, the one step its notice names.
 */
export type EditRevertParams = {
  project: ProjectPath;
  /** The entry to revert. */
  sequence: number;
  /**
   * Whose undo or redo, and the revert entry's author: user, or agent:<name> (default user for edit.undo and
   * edit.redo).
   */
  author?: string;
  /**
   * Put back objects changed since the reverted entry too (otherwise they are listed as conflicts and left
   * alone).
   */
  force?: boolean;
  /** Write even when the revert adds issues of severity error (a person confirming). */
  allow_errors?: boolean;
  /** The revert entry's label (default: undo: <the reverted entry's label>). */
  label?: string;
};
export type EditRevertResult = {
  revision: Revision;
  /** The entry reverted. */
  reverts: number;
  /** The revert entry written (absent when nothing changed). */
  sequence?: number;
  /**
   * "undone: rooms.yml: room:hall changed outline" (redone: for redo, reverted: for edit.revert): what the
   * revert changed.
   */
  changes: Strings;
  /** Objects (file#id) the reverted entry changed and someone changed since: left alone unless force. */
  conflicts: Strings;
  notes?: Strings;
  new_issues: Issues;
  /** Each file the revert changes, in canonical form. */
  files: FileTrees;
};

/**
 * game.playtest: Runs a headless scenario file in the game with the installed builds mounted in front of the
 * asset root (or the shipped maps only), and returns the log lines (PLAY, FAIL, ASSERT, Scenario, WALK, CLICK)
 * and whether it passed. Takes up to a few minutes.
 */
export type GamePlaytestParams = {
  /** The scenario .yml (a path the host can read). */
  scenario: string;
  world: string;
  /** Play the shipped maps only, without the installed builds (to compare). */
  shipped?: boolean;
};
export type GamePlaytestResult = {
  passed: boolean;
  /** The scenario lines, at most 60, then a count of the rest. */
  log: Strings;
};

/**
 * game.play_here: Play here (S5_BROWSER_EDITOR.md 2.10, 3.6): builds the project, installs it into the host's
 * mount of builds (with an outdoor map's terrain material file) and starts the game on it at the pose, through
 * tools/run_game.sh --isolated with the launch directives debug.startup_console_file (`tp` to the pose) and
 * debug.exit_pose_path. Answers once the game is started; the host's notices game_started and game_exited
 * follow, the latter with where the party stood when the game closed. The browser's own: the host answers it, a
 * core never does.
 */
export type GamePlayHereParams = {
  project: ProjectPath;
  /**
   * Where the party stands and looks, as the game's `loc` gives it: the feet, yaw in radians from east toward
   * north, pitch in degrees up.
   */
  pose: {
    position: [number, number, number];
    yaw_radians: number;
    pitch_degrees: number;
    heading_yaw_units?: number;
  };
  /** Show the game's window (the person pressed Play here); else it starts minimised, as agents' runs do. */
  visible?: boolean;
  /**
   * More console lines for the start file, run after the party is put at the pose (test switches: `gold 5000`,
   * `qbit set 12`).
   */
  commands?: string[];
  /** Close the game this many seconds after the map loaded (scripted runs); absent: it stays until closed. */
  seconds?: number;
};
export type GamePlayHereResult = {
  /** The run's name (its folder under output/studio_host/play and tools/run_game.sh's temporary one). */
  run: string;
  map: string;
  world: string;
  kind: "indoor" | "outdoor";
};

/**
 * jobs.start: Queues a job of the project on its lane: checks (check.audit with reach and, indoors, the solve),
 * compare (compare.run), scale_bands (calibration/scale_bands.py: a new dungeon's room sizes), town_feel
 * (calibration/town_feel.py: an outdoor map's figures against the shipped towns), building_shots
 * (calibration/building_shots.py: every building beside the original's in the game; about 35 minutes for two
 * maps), pins_tour (the game's own pictures at the pins' poses: pins.tour, built and installed into the
 * project's play mount), playtest (the project's scenario in the game, `runs` times), lighting_bake (S6: the
 * repository's Cycles bake, tools/lighting/bake_indoor.py or bake_outdoor.py, on the project's build in a
 * scratch hard-link copy of the asset root, never the asset root itself; its lightmap pages and the game's view
 * before and after the bake as pictures; needs Blender and the game). The Python ones run only where python3 is
 * (local mode).
 */
export type JobsStartParams = {
  project: ProjectPath;
  kind: "checks" | "compare" | "scale_bands" | "town_feel" | "building_shots" | "pins_tour" | "playtest" | "lighting_bake";
  params?: JobParams;
};
export type JobsStartResult = {
  job: Job;
};

/**
 * jobs.list: The project's jobs, newest first, without their results (the newest 40 are kept, in
 * <project>/.oymap/jobs/<revision>/<job>/).
 */
export type JobsListParams = {
  project: ProjectPath;
};
export type JobsListResult = {
  jobs: Job[];
};

/** jobs.status: One job of the project with its result. */
export type JobsStatusParams = {
  project: ProjectPath;
  job: string;
};
export type JobsStatusResult = {
  job: Job;
};

/**
 * jobs.cancel: Drops a queued job, or stops a running one by killing lane J's core (started again for the next
 * job) or the job's processes; a killed job leaves no half file.
 */
export type JobsCancelParams = {
  project: ProjectPath;
  job: string;
};
export type JobsCancelResult = {
  job: Job;
};

/**
 * mod.pack: Packs projects into a mod: `<out>/<id>/` with mod.yml (schema mod.schema.json), the maps' files
 * under worlds/<world>/, and the rows they add to or change in engine tables (tables/<table>.append.txt,
 * .override.txt), so that two mods adding map rows do not clash. With `build` (default true) each project is
 * built first; else each must have a build. `maps` declares the mod's map numbers (mod.yml idRanges.maps); a new
 * map numbered outside it is warned of.
 */
export type ModPackParams = {
  /** The projects whose builds it holds. */
  projects: ProjectPath[];
  /** Lower case letters, digits and underscores: the mod's folder. */
  id: string;
  /**
   * A folder for mods. The host maps what a browser names onto its own mods folder ("default"); the core takes
   * the folder as given. The mod is written into <out>/<id>/ (an older pack of the same id replaced).
   */
  out: string;
  name?: string;
  version?: string;
  author?: string;
  description?: string;
  /** [first, last]: the map numbers the mod declares as its own. */
  maps?: [number, number];
  /** Build each project first. Default true. */
  build?: boolean;
};
export type ModPackResult = {
  id: string;
  /** The mod's files, relative to its folder (mod.yml first). */
  files: Strings;
  /** Its maps: new maps and overlays. */
  maps: ({
    file: string;
    world: string;
    kind: "new" | "overlay";
    project: string;
    map_number?: number;
  })[];
  /** The engine tables whose rows it carries. */
  tables: Strings;
  warnings: Strings;
};

/**
 * mod.list: The mods of a mods folder: merged installs (the loose folder the game mounts in front of the named
 * mods: studio_mods.yml), named installs and packed mods (<id>/mod.yml), each with its map numbers and declared
 * range.
 */
export type ModListParams = {
  /**
   * A folder for mods. The host maps what a browser names onto its own mods folder ("default"); the core takes
   * the folder as given.
   */
  mods: string;
};
export type ModListResult = {
  merged: ModEntry[];
  /** Named installs and packed mods (a folder with mod.yml). */
  named: ModEntry[];
};

/**
 * mod.map_number: A free map number (map_stats id) for a new project: the first of the range that no map takes.
 * The range is the mod's (`mod`, by its id in `mods`: mod.yml idRanges.maps), else the world's (world.yml
 * idRanges.maps), else the studio's band 9400 to 9999. Taken: the asset root's map_stats rows, every mod in
 * `mods` (and a merged install's composed table), and the map cards of `projects`. Declared ranges that overlap
 * are warned of.
 */
export type ModMapNumberParams = {
  world: string;
  /**
   * A folder for mods. The host maps what a browser names onto its own mods folder ("default"); the core takes
   * the folder as given.
   */
  mods?: string;
  /** The mod the new map belongs to (its id in `mods`). */
  mod?: string;
  /** Projects whose map numbers are taken too (the host passes all of its own). */
  projects?: ProjectPath[];
};
export type ModMapNumberResult = {
  number: number;
  /** [first, last] of the range it was taken from. */
  range: [number, number];
  /** mod:<id>, world:<world> or studio. */
  from: string;
  /** How many numbers of the range are taken. */
  taken: number;
  warnings: Strings;
};

/**
 * pins.list: The project's pins in the order they were made, optionally only those of one status (a pin without
 * a status is open), and the pins document's counter.
 */
export type PinsListParams = {
  project: ProjectPath;
  status?: Status;
};
export type PinsListResult = {
  counter: Counter;
  pins: Pin[];
};

/**
 * pins.add: Pins a note on an object (a top-level id, with its file where the id is in more than one file) or a
 * point, with the pose it was made from. The core gives the id (pin:p<n>) and stamps the time, the source
 * revision and the lock hash. A picture given as bytes is written beside the pins (.oymap/pins/pictures/,
 * outside git).
 */
export type PinsAddParams = {
  project: ProjectPath;
  text: string;
  /**
   * The object: a top-level id of a source file (door:gate, room:vault), or a keyed sub-object of one in a file
   * of format 1 (room:hall/pillars/pillar2; S5b1 indoor; sketch.yml with S5b2).
   */
  on?: string;
  /** The file of `on`, needed where the id is in more than one file. */
  file?: FileName;
  /** A place, [x, y, z] in map units, for a pin on no object. */
  at?: Point3i;
  pose?: PoseIn;
  world?: string;
  /** The map file the pin is on (6d01.blv). */
  map?: string;
  author?: Author;
  source?: "game" | "studio" | "agent";
  /** The picture of the view the pin was made in (the studio's screenshot), as bytes. */
  picture?: PictureIn;
};
export type PinsAddResult = PinAnswer;

/**
 * pins.claim: An agent takes an open pin (or keeps one it holds). A pin claimed by another is refused unless
 * force.
 */
export type PinsClaimParams = {
  project: ProjectPath;
  pin: PinId;
  by: Author;
  force?: boolean;
};
export type PinsClaimResult = PinAnswer;

/** pins.reply: Adds a reply to a pin's thread (with the source revision now); the status stays. */
export type PinsReplyParams = ActParamsText;
export type PinsReplyResult = PinAnswer;

/**
 * pins.resolve: The agent says what it did: a reply, and the pin open or claimed (by this agent) becomes
 * resolved.
 */
export type PinsResolveParams = ActParamsText;
export type PinsResolveResult = PinAnswer;

/**
 * pins.accept: The person agrees with a resolved pin: it becomes accepted (closed). By the user unless `by` says
 * otherwise.
 */
export type PinsAcceptParams = ActParams;
export type PinsAcceptResult = PinAnswer;

/** pins.reopen: A resolved, accepted or declined pin is open again (its claim cleared), with a reply saying why. */
export type PinsReopenParams = ActParams;
export type PinsReopenResult = PinAnswer;

/** pins.decline: Closes a pin that will not be done, with a reply saying why. */
export type PinsDeclineParams = ActParamsText;
export type PinsDeclineResult = PinAnswer;

/**
 * pins.keep: Keeps the pin's own picture in git on purpose: copies it into review/pictures/ and marks the pin
 * `keep: true` (pictures stay out of git otherwise; S5_BROWSER_EDITOR.md 3.13).
 */
export type PinsKeepParams = {
  project: ProjectPath;
  pin: PinId;
};
export type PinsKeepResult = PinAnswer;

/**
 * pins.import_inbox: Files the game's pins (the `pin <text>` console command writes them with a picture into an
 * inbox folder) into the projects given: a pin goes to the project its map's <stem>.studio.yml names when that
 * is one of them, else to the one project among them that builds or overlays its map. The picture moves into the
 * project's .oymap/pins/pictures/, the pin file into <inbox>/imported/. A pin whose project cannot be told stays
 * in the inbox, listed with the reason.
 */
export type PinsImportInboxParams = {
  /** The inbox folder (the game's debug.pin_inbox_path). A path the host's jail maps. */
  inbox: string;
  projects: ProjectPath[];
  /** Match and report, move nothing. */
  dry_run?: boolean;
};
export type PinsImportInboxResult = {
  imported: ({
    /** The inbox file. */
    file: string;
    /** The project, as given in projects. */
    project: string;
    /** The pin's id in that project (absent on a dry run). */
    pin?: PinId;
    matched_by: "studio_file" | "map";
    /** Whether the pin came with its picture. */
    picture: boolean;
  })[];
  skipped: {
    file: string;
    reason: string;
  }[];
};

/**
 * pins.tour: The shots of a screenshot tour at the pins' poses (`oymap pins tour`): by default every open,
 * claimed and resolved pin with a pose, in the order they were made. The host's pins tour job writes the tour,
 * builds and installs the project and takes the game's own pictures there (S5_BROWSER_EDITOR.md 3.13: after a
 * batch of fixes, the after pictures).
 */
export type PinsTourParams = {
  project: ProjectPath;
  /** Only these pins (pin:p7 ...). */
  pins?: string[];
  /** Only pins of these states (default open, claimed, resolved). */
  status?: ("open" | "claimed" | "resolved" | "accepted" | "declined")[];
};
export type PinsTourResult = {
  /** The map the pins were made on (empty when none says). */
  map: string;
  world: string;
  shots: {
    pin: string;
    /** The picture's name (p7: the tour writes NN-p7.png). */
    name: string;
    /** The party's feet, as `loc` gave it. */
    position: [number, number, number];
    yaw_radians: number;
    pitch_radians: number;
  }[];
  /** Pins without a pose (no shot). */
  skipped: Strings;
};

/**
 * project.open: Every project file as a tree, the source revision, the lock hash, every id and where it is, and
 * the issues found by reading the files against their schemas (check.validate runs the full checks).
 */
export type ProjectOpenParams = {
  project: ProjectPath;
};
export type ProjectOpenResult = {
  revision: Revision;
  lock_hash: LockHash;
  /** The files that exist and parse. A file that does not parse is absent here and named in issues (code yaml). */
  files: FileTrees;
  /** Every object with an id, in file and list order. */
  ids: IdPlace[];
  /** Files that could not be read or parsed, and schema issues. */
  issues: Issues;
  hand_edited?: HandMark;
  /**
   * Every keyed sub-object (format 1, core/Keys.h) by its address (room:hall/pillars/pillar2), with its file:
   * what selections, pins and patches name. A key not written yet reads as the one the core gives.
   */
  keys?: {
    address: string;
    file: FileName;
  }[];
};

/** project.read: One project file: its text as on disk and its tree. */
export type ProjectReadParams = {
  project: ProjectPath;
  file: FileName;
};
export type ProjectReadResult = {
  revision: Revision;
  file: FileName;
  /** The file's bytes as UTF-8 text. */
  text: string;
  /** Whether the text is already in the core's canonical form (oymap fmt would leave it). */
  canonical: boolean;
  /** Absent when the file does not parse. */
  tree?: FileTree;
  /** Present when the file does not parse. */
  parse_error?: string;
};

/**
 * project.status: The project's source revision and lock hash. An edit of a source file made outside the tool
 * since the core last saw the project is recorded in its history (under .oymap/, author outside until
 * project.record names one) and listed; a lock changed from outside is taken as the new record and noted in
 * .oymap/lock.log.
 */
export type ProjectStatusParams = {
  project: ProjectPath;
};
export type ProjectStatusResult = {
  revision: Revision;
  lock_hash: LockHash;
  /** The semantic diff of an outside edit found by this call: "rooms.yml: room:hall changed outline". */
  outside_changes: Strings;
  /**
   * Files that do not parse now (a generator half way, a typo in a text editor), with the parser's message;
   * absent when every file parses. The project is read only until they parse (S5_BROWSER_EDITOR.md 2.4.3).
   */
  unreadable?: {
    file: string;
    message: string;
  }[];
  /** The history entry this read recorded for an edit made outside the tool. */
  outside_sequence?: number;
  /**
   * That entry's error notice: a project edited by hand rewritten from outside (objects a person changed last
   * that it replaced, keys it dropped), with the one step to revert it.
   */
  outside_notice?: Strings;
  hand_edited?: HandMark;
};

/**
 * project.record: Puts an author and a label on the edits made outside the tool (a generator run, a text
 * editor): the change on disk now is recorded first, then every unattributed outside entry since this author's
 * latest entry takes the author and the label. Nothing else in the entries changes; the entries taken are
 * listed, so one claimed by mistake is seen.
 */
export type ProjectRecordParams = {
  project: ProjectPath;
  /** user, or agent:<name>. */
  author: string;
  label?: string;
};
export type ProjectRecordResult = {
  revision: Revision;
  recorded: {
    /** The history entry's number. */
    sequence: number;
    changes: Strings;
  }[];
};

/**
 * project.lock_prune: Drops the id lock's entries of ids no source file has any more (builds keep them, so a
 * number once given stays through undo). A deliberate step before sharing or shipping a map, or when a build
 * says a table has no free number; written as a record (.oymap/lock.log), never undone. Outdoor and overlay
 * projects keep every entry (a note says why).
 */
export type ProjectLockPruneParams = {
  project: ProjectPath;
  /** List what would be dropped; write nothing. */
  dry_run?: boolean;
};
export type ProjectLockPruneResult = {
  /** "events: evt:gone 3": the table, the id and its number. */
  dropped: Strings;
  lock_hash_before: LockHash;
  /** The lock's hash now (as before on a dry run). */
  lock_hash: LockHash;
  note?: string;
};

/**
 * project.new: Makes an empty project in a folder that holds none. Indoor (the default): a map card, one masonry
 * theme, no rooms yet (so it reports one issue until the first room and the start exist); the first edit adds
 * rooms, the openings between them and the start together. Outdoor (S5b2): a map card, a plan with one space and
 * its arrival, and a sketch of level land given by spot heights (heights.grid) with the arrival point in the
 * middle: it validates and builds as made.
 */
export type ProjectNewParams = {
  /** The folder to make (made when missing; refused when it holds a project already). */
  project: ProjectPath;
  /** The map's file stem, lower case (crypt01 builds crypt01.blv). */
  id: string;
  /** The map's name as the player reads it. */
  name: string;
  /** Default mm6. */
  world?: string;
  /** A shipped map of the world whose map_stats row the new map starts from (monsters, music); default 6d01.blv. */
  reference?: string;
  /** The number of the map's row in the map table; each new map needs its own (default 9400). */
  stats_id?: number;
  /** indoor (the default) or outdoor. */
  kind?: "indoor" | "outdoor";
};
export type ProjectNewResult = {
  /** The files made, relative to the project folder. */
  files: Strings;
  revision: Revision;
  /** What to do first. */
  next: string;
};

/**
 * project.query: Reads one object by id (with the engine number the last build gave it, from ids.lock.yml), one
 * top-level list by its key, or without either the project's summary: the map card and the ids of each file's
 * lists.
 */
export type ProjectQueryParams = {
  project: ProjectPath;
  id?: ObjectId;
  /** A top-level key of a source file whose value is a list (doors, rooms, events). */
  list?: string;
  /** The file of `id` or `list`, needed where it is in more than one file. */
  file?: FileName;
};
export type ProjectQueryResult = {
  revision: Revision;
  file?: FileName;
  list?: string;
  /** The object as stored (with `id`). */
  object?: JsonObject;
  /** The list as stored (with `list` without `id`). */
  items?: JsonValue;
  /** The engine number the build gave the id (the event number check.flow_event takes, a door's id). */
  number?: number;
  /** The table of ids.lock.yml the number is in (events, doors, sectors ...). */
  number_of?: string;
  /** The map card's own words (summary only). */
  card?: {
    [key: string]: string;
  };
  /** Summary only: per file, each list's ids (60 at most, then a count of the rest). */
  files?: {
    [key: string]: {
      [key: string]: Strings;
    };
  };
};

/**
 * project.import: A shipped map as an overlay project (`oymap import`) in a folder that holds no project yet:
 * the map card, a derived room graph, and the map's own numbers under stable ids (door:d12, evt:e20, room:s3) in
 * ids.lock.yml. The geometry stays in the base map.
 */
export type ProjectImportParams = {
  /** The folder to make the project in. */
  project: ProjectPath;
  /** The shipped map's file name (6d01.blv). */
  map: string;
  world: string;
};
export type ProjectImportResult = {
  map: string;
  /** The files made, relative to the project. */
  written: Strings;
};

/**
 * project.fmt: Rewrites a project's files in canonical form (`oymap fmt`), or with `check` only names the files
 * that are not. A rewrite is an edit made outside the operations: the next read records it in the history as
 * one.
 */
export type ProjectFmtParams = {
  project: ProjectPath;
  /** Only name the files not in canonical form; write nothing. */
  check?: boolean;
};
export type ProjectFmtResult = {
  checked_only: boolean;
  /** Files not in canonical form (rewritten unless `check`). */
  not_canonical: Strings;
};

/**
 * project.protect: "Protect this project" (S5_BROWSER_EDITOR.md 2.8): a person sets the hand-edit mark by hand
 * (for one who edits the YAML in a text editor), or clears it (clear: a generator run then erases hand edits).
 * Written as a transaction of author user; no agent and no procedure calls it.
 */
export type ProjectProtectParams = {
  project: ProjectPath;
  /** Clear the mark instead. */
  clear?: boolean;
};
export type ProjectProtectResult = {
  revision: Revision;
  marked: boolean;
  hand_edited?: HandMark;
  /** The history entry written (absent when nothing changed). */
  sequence?: number;
};

/**
 * project.migrate: Writes every source file in canonical form with the keys of format 1 (rooms.yml and
 * objects.yml: every room's pillars, platforms, levels ... and every mover's part gets the key it reads as), as
 * one history entry of author migration. The browser never migrates by itself; it asks.
 */
export type ProjectMigrateParams = {
  project: ProjectPath;
  dry_run?: boolean;
};
export type ProjectMigrateResult = {
  revision: Revision;
  /** The files rewritten (or for a dry run that would be). */
  files: Strings;
  keys_written: number;
  sequence?: number;
};

/**
 * project.resolve: The effective values of one object for the inspector (S5_BROWSER_EDITOR.md 3.8): its written
 * fields, the values it takes when a field is not written (a room's theme and ambient from rooms.yml defaults,
 * its surfaces from its theme) with where each comes from, and its resolved geometry from the view's lowering
 * (view.layout's entry). A spawn point also gets the map card's encounter slots it draws on (`slots`). With
 * `card: true` and no `id`: the map card (project.yml map_stats) as the game will read it: the columns it
 * writes, those it takes from its reference map's row of map_stats.txt (source reference; needs the asset root),
 * and its encounter slots.
 */
export type ProjectResolveParams = {
  project: ProjectPath;
  id?: ObjectId;
  file?: FileName;
  /** The map card itself (no `id`). */
  card?: boolean;
};
export type ProjectResolveResult = {
  id: string;
  file: FileName;
  list: string;
  fields: {
    [key: string]: {
      value: JsonValue;
      source: "written" | "default" | "theme" | "reference";
      from?: string;
    };
  };
  /** The object's entry in view.layout (resolved geometry in world units). */
  layout?: JsonObject;
  layout_stale?: boolean;
  /**
   * The map card's encounter slots 1 to 3 (a spawn point's, or the card's): the monster family, its picture
   * where it differs, difficulty, monsters per spawn point and share of rest encounters as map_stats.txt has
   * them, and whether project.yml writes the slot (`written`) or the reference map's row gives it (`reference`).
   */
  slots?: ({
    slot: number;
    monster: string;
    picture?: string;
    tier?: string;
    count?: string;
    weight?: string;
    source: "written" | "reference";
    from: string;
  })[];
  /** Why the reference map's row was not read (no asset root, no row). */
  card_note?: string;
};

/**
 * session.hello: The core's version, the catalogue's version, the project formats it reads, its methods and what
 * this backend can do. The host adds its own capabilities (mode, game, jobs) before passing it on.
 */
export type SessionHelloParams = NoParams;
export type SessionHelloResult = {
  core_version: string;
  rpc_version: number;
  backend: "native" | "wasm";
  /** Whether the session has an asset root (session.configure). */
  asset_root: boolean;
  /** The format number of each project file this core reads and writes. */
  formats: {
    [key: string]: number;
  };
  /** Every method of the catalogue this core serves, by full name. */
  methods: Strings;
  /**
   * Added by the studio host or the hosted page's worker (never by a core): its mode and capabilities. `python`:
   * the Python checks of the repository run as jobs here (D10: local only). Hosted mode (S5c): no game, no jobs,
   * no Python.
   */
  host?: {
    mode: "local" | "hosted";
    game: boolean;
    assets: boolean;
    version: string;
    jobs?: boolean;
    python?: boolean;
  };
};

/**
 * session.configure: Sets or clears the session's asset root (the folder holding engine/ and worlds/) and its
 * mount of builds. Called by the host or the worker that owns the core, never passed on from a browser or an
 * agent.
 */
export type SessionConfigureParams = {
  /** Absent: the session has no asset root. */
  asset_root?: string;
  /**
   * The folder builds are installed into (build.install) and read from (`built`): never assets_dev. Absent:
   * none.
   */
  mount?: string;
};
export type SessionConfigureResult = {
  asset_root: boolean;
  /** Whether the session has a mount. */
  mount?: boolean;
};

/**
 * session.release: Drops what the core keeps of a project (its files as last read, validation, view, kept land;
 * S5_BROWSER_EDITOR.md 2.4.3): the hosted page's worker keeps one map at a time (PLAN.md 9) and releases the
 * project it closes. Nothing on disk changes; the next call that names the project reads it again. Called by the
 * host or the worker that owns the core, never passed on from a browser or an agent.
 */
export type SessionReleaseParams = {
  project: ProjectPath;
};
export type SessionReleaseResult = {
  /** Whether the core kept anything of the project. */
  released: boolean;
};

/** session.schema: The project format's schemas: without `name` their list, with it one schema as JSON. */
export type SessionSchemaParams = {
  /**
   * A schema: rooms, objects, wiring, plan, project, sketch, atmosphere, pins, common, ids_lock (or its file
   * name).
   */
  name?: string;
};
export type SessionSchemaResult = {
  schemas?: {
    name: string;
    title: string;
  }[];
  /** The schema file returned. */
  name?: string;
  /** The schema (JSON Schema 2020-12). */
  schema?: JsonObject;
};

/**
 * view.layout: Every object's resolved place: rooms (outline, floor and ceiling as built), openings (where in
 * which walls), doors, lifts and movers, things that stand somewhere (chests, monsters, items, decorations,
 * lights, spawn points, the start; switches and exits at the middle of their faces), and outdoors the land's
 * heights and the models' boxes. What the plan view draws and what a pick on the plan maps back to.
 */
export type ViewLayoutParams = {
  project: ProjectPath;
};
export type ViewLayoutResult = {
  revision: Revision;
  /** The revision the layout was made from: equal to revision unless stale. */
  view_revision: Revision;
  /** The project's own revision does not lower (it has errors): this is the last layout made of it. */
  stale: boolean;
  kind: "indoor" | "outdoor" | "overlay";
  world: string;
  bounds: ViewBox;
  rooms: ViewRoom[];
  openings: ViewOpening[];
  doors: ViewDoor[];
  lifts: ViewLift[];
  things: ViewThing[];
  start?: ViewStart;
  /** Outdoors: the land as built. */
  land?: ViewLand;
  /** Outdoors: the models (buildings and other structures) and their boxes. */
  models?: ViewModel[];
  /**
   * A view build (S5_BROWSER_EDITOR.md 2.4.2): the objects the lowering could not lower, left out of this view
   * with what depends on them; the issues carry a note (code skipped) for each. The client draws their last good
   * mesh marked stale.
   */
  skipped?: Strings;
  /**
   * With skipped: a note (code skipped) per object left out, and the errors the view build reached that the full
   * check had stopped before.
   */
  skipped_issues?: Issues;
};

/**
 * view.mesh: The map's visible faces as binary buffers, grouped by texture, with a provenance table naming the
 * project object each face comes from. The bytes are written to a cache file under the project's .oymap/view/
 * (named by the view's revision and lock hash) and named in `file`; the host serves them on its byte route
 * (/mesh/<project>/<name>) and the hosted worker hands them over as a buffer. Layout of the file (little-endian,
 * each section 4-byte aligned, offsets and counts in `sections`): positions float32 x,y,z per vertex (map
 * units); normals float32 x,y,z per vertex (unit length); uvs float32 u,v per vertex in texels of the face's
 * texture (divide by the texture's own size, as the game does), except where the group says uv_unit unit (0..1
 * across the texture); indices uint32, three per triangle, each group's triangles contiguous; triangle_faces
 * uint32, one per triangle, the face it belongs to; face_owners uint32, one per face, a place in `owners` (0:
 * none).
 */
export type ViewMeshParams = {
  project: ProjectPath;
};
export type ViewMeshResult = {
  revision: Revision;
  /** The revision the mesh was made from: equal to revision unless stale. */
  view_revision: Revision;
  /** The project's own revision does not lower (it has errors): this is the last mesh made of it. */
  stale: boolean;
  lock_hash: LockHash;
  kind: "indoor" | "outdoor" | "overlay";
  /** The world whose textures the faces name (project.yml world). */
  world: string;
  /**
   * The cache file, relative to the project: .oymap/view/<view revision>-<first 8 digits of the lock
   * hash>-<first 12 digits of the bytes' hash>.mesh (a name never stands for two contents, as the host serves it
   * immutable).
   */
  file: string;
  /** The file's size. */
  bytes: number;
  counts: {
    vertices: number;
    triangles: number;
    faces: number;
  };
  sections: {
    positions: MeshSection;
    normals: MeshSection;
    uvs: MeshSection;
    indices: MeshSection;
    triangle_faces: MeshSection;
    face_owners: MeshSection;
  };
  /** Runs of triangles that share a texture, in the order of `indices`. */
  groups: MeshGroup[];
  /** The objects faces come from; the first entry is the empty owner (id ""). */
  owners: MeshOwner[];
  bounds: ViewBox;
  /**
   * A view build (S5_BROWSER_EDITOR.md 2.4.2): the objects the lowering could not lower, left out of this view
   * with what depends on them; the issues carry a note (code skipped) for each. The client draws their last good
   * mesh marked stale.
   */
  skipped?: Strings;
  /**
   * With skipped: a note (code skipped) per object left out, and the errors the view build reached that the full
   * check had stopped before.
   */
  skipped_issues?: Issues;
};

/**
 * view.render: A labelled drawing of a shipped map or a project from its data, as PNG: plan (top down) or iso.
 * Indoor: sectors numbered and coloured, doors red with their numbers, portals green, S the party start, yellow
 * dots spawn points. Outdoor: terrain by height, buildings numbered, clickable faces orange.
 */
export type ViewRenderParams = {
  map: MapTarget;
  /** The world of a shipped map (mm6, mm7, mm8, mm9); a project names its own. */
  world?: string;
  /** Read with the session's mount of installed builds in front of the asset root (after build.install). */
  built?: boolean;
  view?: "plan" | "iso";
  /** The longer side in pixels (default 1024). */
  size?: number;
  /** Numbers and names on the drawing (default true). */
  labels?: boolean;
};
export type ViewRenderResult = {
  /** The map file drawn (a project's built map). */
  map: string;
  width: number;
  height: number;
  /** The PNG, base64 (no path: the picture is the answer). */
  png_base64: string;
};

/**
 * view.original_mesh: The project's original (its map_stats.reference, or the shipped map it overlays) as the
 * views draw a mesh, read from the session's asset root: indoor every visible face as the map file stores it,
 * each owned by its sector (sector:<n>, no file); outdoor the land by its tiles and the models. Written beside
 * the project's own view meshes (.oymap/view/); the Compare view draws it beside the rebuild, moved by
 * compare.run's vertical_offset.
 */
export type ViewOriginalMeshParams = {
  project: ProjectPath;
  /**
   * Another shipped map of the project's world instead of its own original. A shipped map's file name, never a
   * path.
   */
  original?: string;
};
export type ViewOriginalMeshResult = {
  /** The original's map file. */
  original: string;
  /** The world whose textures the faces name (project.yml world). */
  world: string;
  kind: "indoor" | "outdoor" | "overlay";
  /**
   * The cache file, relative to the project: .oymap/view/<view revision>-<first 8 digits of the lock
   * hash>-<first 12 digits of the bytes' hash>.mesh (a name never stands for two contents, as the host serves it
   * immutable).
   */
  file: string;
  /** The file's size. */
  bytes: number;
  counts: {
    vertices: number;
    triangles: number;
    faces: number;
  };
  sections: {
    positions: MeshSection;
    normals: MeshSection;
    uvs: MeshSection;
    indices: MeshSection;
    triangle_faces: MeshSection;
    face_owners: MeshSection;
  };
  /** Runs of triangles that share a texture, in the order of `indices`. */
  groups: MeshGroup[];
  /** The objects faces come from; the first entry is the empty owner (id ""). */
  owners: MeshOwner[];
  bounds: ViewBox;
};

/**
 * view.render_sketch: The plan picture of an outdoor project's sketch.yml (`oymap render-sketch`): land, water,
 * roads, districts, plots, points, areas, drawn from what can be read (also a sketch that still has issues). As
 * PNG bytes in the answer.
 */
export type ViewRenderSketchParams = {
  project: ProjectPath;
  /** Pixels across (256 to 4096; default 1024). */
  size?: number;
  /** x, y, width, depth in cells: only that part of the map. */
  region?: [number, number, number, number];
  labels?: boolean;
};
export type ViewRenderSketchResult = {
  width: number;
  height: number;
  /** The PNG, base64. */
  png_base64: string;
};

/**
 * view.layout_at: History's "show as it was" (S5_BROWSER_EDITOR.md 3.12): view.layout's members for the project
 * as it stood before (side before, the default) or after (side after) a history entry, lowered from the files of
 * then (each file taken back through the entries after it), for the views to draw as a ghost over the current.
 * Indoor and outdoor projects (outdoor since S5b2: the land and the models). Nothing is kept or written.
 */
export type ViewLayoutAtParams = {
  project: ProjectPath;
  /** The history entry (edit.history's sequence). */
  sequence: number;
  /** Before the entry (default) or after it. */
  side?: "before" | "after";
};
export type ViewLayoutAtResult = {
  sequence: number;
  side: "before" | "after";
  /** The source revision of the files of then. */
  revision: Revision;
  kind: "indoor" | "outdoor";
  world: string;
  /** Objects the lowering of then left out. */
  skipped?: Strings;
  bounds: ViewBox;
  rooms: ViewRoom[];
  openings: ViewOpening[];
  doors: ViewDoor[];
  lifts: ViewLift[];
  things: ViewThing[];
  start?: ViewStart;
  /** Outdoors: the land as it was. */
  land?: ViewLand;
  /** Outdoors: the models as they were. */
  models?: ViewModel[];
};

/**
 * view.terrain_query: The built land of an outdoor project, asked by place (S5_BROWSER_EDITOR.md 3.18: how
 * agents read land a person made by hand, instead of reading its rows): the height and slope at points, and a
 * profile along a line. From the current view's map (the stored heights, as the game has them); stale when the
 * project's own revision does not lower.
 */
export type ViewTerrainQueryParams = {
  project: ProjectPath;
  /** Places [x, y] in cells (fractions allowed) to give the height and slope at. */
  points?: [JsonValue, JsonValue][];
  /** A profile: heights every `step` cells from `from` to `to`. */
  line?: {
    from: [JsonValue, JsonValue];
    to: [JsonValue, JsonValue];
    /** Cells between samples, 0.25 to 16 (1 when left out). */
    step?: number;
  };
};
export type ViewTerrainQueryResult = {
  revision: Revision;
  view_revision: Revision;
  stale: boolean;
  skipped?: Strings;
  skipped_issues?: Issue[];
  points: {
    at: number[];
    /** Map units, as stored (steps of 32 between the nodes, weighed by distance). */
    height: number;
    /** Degrees from level, from the heights half a cell either way. */
    slope: number;
  }[];
  profile?: {
    at: number[];
    height: number;
  }[];
};

/**
 * view.overlay: An overlay project's scene things on its base map (devdocs/map_studio/S6_PLAN.md, item O; S8a),
 * for the plan view and agents: the base map's pulsing lights, ambient sounds, destructibles, water volumes,
 * spawn points and ladders, each with its id in ids.lock.yml and what the project does to it (kept, changed,
 * removed), and the project's own additions (objects.yml `scene`: also monsters and floor items, which the game
 * appends after the base map's) where the built overlay puts them; with the base map's bounds and profile
 * (region, city, dungeon), and its cinematics with what the project's of the same name do to them. Read from the
 * session's asset root (the base map's own scene, without other overlays).
 */
export type ViewOverlayParams = {
  project: ProjectPath;
};
export type ViewOverlayResult = {
  /** The base map's file. */
  base: string;
  world: string;
  profile: "region" | "city" | "dungeon";
  /** [min x, min y, max x, max y] of the base map's vertices. */
  bounds: [number, number, number, number];
  /** The scene overlay's keys the project writes (empty: it changes no scene). */
  scene_keys: string[];
  things: ({
    /** Its id: in ids.lock.yml for a base thing, in objects.yml `scene` for an addition. */
    id: string;
    kind: "light" | "sound" | "destructible" | "water" | "spawn" | "ladder" | "monster" | "item";
    origin: "base" | "added";
    state: "kept" | "changed" | "removed" | "added";
    /**
     * Its place [x, y, z]: a light's or sound's position, a destructible's centre, a water volume's middle at
     * its surface, a spawn point, a ladder's foot, a monster's or an item's place.
     */
    at: [number, number, number];
    /** A light's largest reach, a sound's hearing distance, a spawn's spread, a monster's body. */
    radius?: number;
    label: string;
    /** A water volume's pieces on the plan. */
    polygons?: [number, number][][];
  })[];
  /**
   * The base map's cinematics and the project's (wiring.yml `cinematics`, written as `<stem>_<project
   * id>.cinematics.yml`, which the game merges by name after the map's own): a base one kept or replaced by the
   * project's of its name, the project's others added. Absent when neither has any.
   */
  cinematics?: ({
    /** `cinematic:<name>`. */
    id: string;
    state: "kept" | "replaced" | "added";
  })[];
  /** What stops the overlay from building (its additions are then left out). */
  issues: {
    file: string;
    path: string;
    message: string;
  }[];
};

/**
 * walk.load: Reads a built map and its movement state and makes the walk: the party stands where the map starts
 * it until walk.place. Replaces any walk this core had.
 */
export type WalkLoadParams = {
  /** The built .blv or .odm. */
  map: string;
  /** Its <stem>.walk.yml, written by the build beside it. */
  state: string;
  /** The asset root's engine/data_tables/decoration_data.txt. */
  decorations: string;
  /** Outdoors: its <stem>.walk.terrain, written by the build beside it. */
  terrain?: string;
};
export type WalkLoadResult = {
  kind: "indoor" | "outdoor";
  /** The map's faces (outdoors: its models'). */
  faces: number;
  /** Decorations the party bumps into. */
  decoration_colliders: number;
  party: WalkParty;
  /** The doors, lifts and movers walk.toggle moves (indoors), by project id, as the map starts them. */
  doors: WalkDoor[];
  pose: WalkPose;
};

/**
 * walk.place: Puts the party where an eye at that point would be (the studio's camera); the next steps let it
 * settle on the floor as the game does.
 */
export type WalkPlaceParams = {
  /** [x, y, z] of the eye, world units. */
  eye: [number, number, number];
};
export type WalkPlaceResult = {
  pose: WalkPose;
};

/**
 * walk.step: Moves the party for `frames` frames of `seconds` each with the keys held and facing `yaw_radians`,
 * as the game's frame does (an accumulator and 1/128 s movement steps); the pose after the last.
 */
export type WalkStepParams = {
  /** Facing, radians from east (+x) toward north (+y). */
  yaw_radians: number;
  buttons: WalkButtons;
  /** The frame's length (the game caps the movement owed at 0.1 s). */
  seconds: number;
  /** Frames of the same input (1 when absent). */
  frames?: number;
};
export type WalkStepResult = {
  pose: WalkPose;
};

/**
 * walk.replay: A recorded walk: frame after frame of [yaw_radians, buttons, seconds], and at a frame `toggle` a
 * door (before that frame). Returns the pose after the last frame and a hash of every frame's pose bits, the
 * same in the native and the WebAssembly core.
 */
export type WalkReplayParams = {
  /** Where the walk starts: as walk.place. */
  eye: [number, number, number];
  frames: [number, number, number][];
  /** Doors toggled before a frame: {frame, door}. */
  toggles?: {
    frame: number;
    door: string;
  }[];
  /** Also return every n-th frame's pose bits (0 or absent: none). */
  trace_every?: number;
};
export type WalkReplayResult = {
  frames: number;
  /** FNV-1a 64 of every frame's pose bits, 16 hex digits. */
  hash: string;
  pose: WalkPose;
  /** Every trace_every-th frame's pose bits. */
  trace?: Strings;
};

/**
 * walk.toggle: Opens a shut door, lift or mover of the project at once, or shuts an open one: its end state as
 * an event would leave it. Indoors only.
 */
export type WalkToggleParams = {
  /** Its project id (door:closet). */
  door: string;
};
export type WalkToggleResult = {
  door: string;
  open: boolean;
};

/**
 * world.view: The maps of projects by world and the links between them: every project is a map of its world (its
 * own file; an overlay's base), every neighbour of its map card (an exit, a map edge, a boat, a fall ...) a link
 * to another project's map or to a shipped map. A rebuild (map_stats.reference) or an overlay (base) stands for
 * its original: a link naming the original reaches it (`via_original`). Each link lists the objects that use the
 * neighbour (an exit naming it, a building whose way in names its map); ways out the card does not declare are
 * links of kind `undeclared`. Read from the files, without a build; with an asset root the shipped maps carry
 * their names from map_stats.
 */
export type WorldViewParams = {
  /** The projects (the host passes its own: host.projects). */
  projects: ProjectPath[];
  /** Only this world's maps. */
  world?: string;
};
export type WorldViewResult = {
  worlds: ({
    world: string;
    maps: ({
      /** The map's file (a project's own; an overlay's base; a shipped map as the links name it). */
      map: string;
      kind: "indoor" | "outdoor" | "unknown";
      /**
       * new (a map of its own), rebuild (of a shipped map), overlay (changes a shipped map), shipped (a map no
       * project makes).
       */
      role: "new" | "rebuild" | "overlay" | "shipped";
      name: string;
      /** The project's index in `projects`. */
      project?: number;
      /** A rebuild's original or an overlay's base. */
      stands_for?: string;
    })[];
    links: ({
      /** Its map's index in `maps`. */
      from: number;
      to: number;
      /** The neighbour's id in the map card (empty for an undeclared way out). */
      id: string;
      /**
       * edge, door, boat, stable, teleport, fall, roof, pyramid, mirror, scripted, empty (the card gives none),
       * or undeclared (a way out the files name, by `map:`, that no neighbour of the card names).
       */
      kind: string;
      side?: "north" | "south" | "east" | "west";
      days?: number;
      /** The map the card names. */
      target: string;
      via_original: boolean;
      /** The ids of the objects that use the neighbour. */
      exits: Strings;
    })[];
  })[];
  /** Projects left out, and why. */
  skipped: {
    project: number;
    reason: string;
  }[];
};

